INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(489267, 47478, 4493, '<td valign="top">Nice concept. Crop a little more off the right and see about getting the camera angle more pleasing. The ashtray feels like it''s about to fall out of the frame. 6 -danny</td>', 'Nice concept. Crop a little more off the right and see about getting the camera angle more pleasing. The ashtray feels like it''s about to fall out of the frame. 6 -danny', '2003-11-19 00:10:32.000000', NULL, 1),
(489271, 47099, 4493, '<td valign="top">This image doesn''t do anything for me. Lighting is fair, overall shot is soft. 5 -danny</td>', 'This image doesn''t do anything for me. Lighting is fair, overall shot is soft. 5 -danny', '2003-11-19 00:11:43.000000', NULL, 1),
(489272, 47223, 12253, '<td valign="top">Wow.  Believeable and powerful.  Some technical notes: I would guess you were going for dark tones, but I think a bit more contrast would have helped.  Also, I think the light falloff towards the left is a bit too delineated and sudden.  If it were mine, I am not sure whether I would have cropped it or tried for a more gradual drop off.  Overall: Superb!</td>', 'Wow.  Believeable and powerful.  Some technical notes: I would guess you were going for dark tones, but I think a bit more contrast would have helped.  Also, I think the light falloff towards the left is a bit too delineated and sudden.  If it were mine, I am not sure whether I would have cropped it or tried for a more gradual drop off.  Overall: Superb!', '2003-11-19 00:11:45.000000', NULL, 1),
(489274, 47247, 4493, '<td valign="top">soft, not well lit, blurry, don''t even see the whole cigarette. 4 -danny</td>', 'soft, not well lit, blurry, don''t even see the whole cigarette. 4 -danny', '2003-11-19 00:12:29.000000', NULL, 1),
(489275, 47408, 10848, '<td valign="top">cute and funny, at least it not a snapshot of newspapers and books, I like it, very well excuted and the colors are great, good focus, (9)</td>', 'cute and funny, at least it not a snapshot of newspapers and books, I like it, very well excuted and the colors are great, good focus, (9)', '2003-11-19 00:13:25.000000', NULL, 1),
(489276, 47266, 4493, '<td valign="top">It''s ok to use your flash during the day. A fill flash on the bird might add more interest to this shot. 5 -danny</td>', 'It''s ok to use your flash during the day. A fill flash on the bird might add more interest to this shot. 5 -danny', '2003-11-19 00:13:28.000000', NULL, 1),
(489278, 47506, 4493, '<td valign="top">? I don''t get this. I guess I could go to united airlines website and do some research, but since I am not going to do that, Decent lighting, but nothing to spark my interest. 5 -danny</td>', '? I don''t get this. I guess I could go to united airlines website and do some research, but since I am not going to do that, Decent lighting, but nothing to spark my interest. 5 -danny', '2003-11-19 00:14:48.000000', NULL, 1),
(489279, 46852, 12253, '<td valign="top">Well, I am not sure if your title was to evoke a response.  While this woman has a great powerful look, the cigarette to me is a weakness.  And a cigarette makes one anything but beautiful.  So I am not sure what to make of this topically, though it is very well taken.  The bit of smoke to the right center is a distraction (as is the whole cigarette).</td>', 'Well, I am not sure if your title was to evoke a response.  While this woman has a great powerful look, the cigarette to me is a weakness.  And a cigarette makes one anything but beautiful.  So I am not sure what to make of this topically, though it is very well taken.  The bit of smoke to the right center is a distraction (as is the whole cigarette).', '2003-11-19 00:14:55.000000', NULL, 1),
(489280, 47504, 4493, '<td valign="top">Heh heh, nice use of these guys. Very well lit too. Your composition is pleasing and the message comes across clear. Good choice to go b/w. 8 -danny</td>', 'Heh heh, nice use of these guys. Very well lit too. Your composition is pleasing and the message comes across clear. Good choice to go b/w. 8 -danny', '2003-11-19 00:15:45.000000', NULL, 1),
