(489719, 47569, 14094, '<td valign="top">A better title might have been "American Liberation -- Love it or Die."  Contrast is far too deep here.</td>', 'A better title might have been "American Liberation -- Love it or Die."  Contrast is far too deep here.', '2003-11-19 08:33:50.000000', NULL, 1),
(489720, 47724, 14094, '<td valign="top">Good symbolism here, except the star of David should really be on the cloth that binds.  The artist is certainly pro-Israeli, so the "attempt at resistance" doesn''t make much sense.  However, the message is VERY clear, so this deserves some recognition.</td>', 'Good symbolism here, except the star of David should really be on the cloth that binds.  The artist is certainly pro-Israeli, so the "attempt at resistance" doesn''t make much sense.  However, the message is VERY clear, so this deserves some recognition.', '2003-11-19 08:35:32.000000', NULL, 1),
