(489723, 46848, 4493, '<td valign="top">:-) I''ve seen these all over the place for sale. I even know someone who bought some. This does capture the capitalistic aspect of war. 6 -danny</td>', ':-) I''ve seen these all over the place for sale. I even know someone who bought some. This does capture the capitalistic aspect of war. 6 -danny', '2003-11-19 08:37:56.000000', NULL, 1),
(489727, 47375, 14094, '<td valign="top">Funny, that we have a night shot for a Sieze the Day caption.</td>', 'Funny, that we have a night shot for a Sieze the Day caption.', '2003-11-19 08:47:36.000000', NULL, 1),
