(490727, 47723, 10170, '<td valign="top">The lighting really makes this one, and therefore ties in excellently with the title.</td>', 'The lighting really makes this one, and therefore ties in excellently with the title.', '2003-11-20 05:21:43.000000', NULL, 1),
(490728, 47052, 10170, '<td valign="top">Absolutely stunning photo.</td>', 'Absolutely stunning photo.', '2003-11-20 05:24:18.000000', NULL, 1),
