(490737, 46730, 10170, '<td valign="top">Footy supports methinks *laugh*  But really greay shot.  You''ve managed to capture just the right amount of motion blur.</td>', 'Footy supports methinks *laugh*  But really greay shot.  You''ve managed to capture just the right amount of motion blur.', '2003-11-20 05:33:01.000000', NULL, 1),
