(490748, 47703, 10170, '<td valign="top">What a sensational fish!  Black background works well, lighting on the fish is excellent.  I find the glare at the top a little distracting, but no worse than that.</td>', 'What a sensational fish!  Black background works well, lighting on the fish is excellent.  I find the glare at the top a little distracting, but no worse than that.', '2003-11-20 05:50:56.000000', NULL, 1),
(490750, 47606, 10170, '<td valign="top">Beautiful, simply beautiful.</td>', 'Beautiful, simply beautiful.', '2003-11-20 05:52:14.000000', NULL, 1),
(490761, 47392, 14260, '<td valign="top">very nice</td>', 'very nice', '2003-11-20 06:51:29.000000', NULL, 1),
