(492263, 47541, 2170, '<td valign="top">very well-done.  i was going to try something exactly like this, but i couldn''t find such a cool hammer.</td>', 'very well-done.  i was going to try something exactly like this, but i couldn''t find such a cool hammer.', '2003-11-22 09:26:25.000000', NULL, 1),
(492272, 47594, 7628, '<td valign="top">This ia a beautiful garden.  The composition is a bit chaotic, although I do like the corner of silver leaves.  The light onthe silver is a bit bright and washes out the details, and the light on the rest of the flowers is flat and doesn''t help to bring out any details.  I''d be interestedin seeing a tighter composition of the flaming pink leaves against a background on the silver leaves.</td>', 'This ia a beautiful garden.  The composition is a bit chaotic, although I do like the corner of silver leaves.  The light onthe silver is a bit bright and washes out the details, and the light on the rest of the flowers is flat and doesn''t help to bring out any details.  I''d be interestedin seeing a tighter composition of the flaming pink leaves against a background on the silver leaves.', '2003-11-22 10:25:55.000000', NULL, 1),
(492273, 47248, 7628, '<td valign="top">Dramatic composition. Good idea for the challenge, plus this is propanda I like to see.  Good focus on the skin, a wonder if a tadmore contrast would bring out a bit more?  I do like the narrow DOF gives us a feel of where the fist is coming from, seeing the arm disappearing down below. 9</td>', 'Dramatic composition. Good idea for the challenge, plus this is propanda I like to see.  Good focus on the skin, a wonder if a tadmore contrast would bring out a bit more?  I do like the narrow DOF gives us a feel of where the fist is coming from, seeing the arm disappearing down below. 9', '2003-11-22 10:29:31.000000', NULL, 1),
(492278, 47616, 10414, '<td valign="top">This is a very POWERFUL picture that just SCREAMS propaganda!! I know the blurring effect was probably intentional, but I would like to have seen a little more focus on the syringe. Maybe taking the picture at a different angle would have captured more of the syringe clearly. With that said, so far, this is the only photo that has given me a powerful message!!  Wonderful creativity!!!   9</td>', 'This is a very POWERFUL picture that just SCREAMS propaganda!! I know the blurring effect was probably intentional, but I would like to have seen a little more focus on the syringe. Maybe taking the picture at a different angle would have captured more of the syringe clearly. With that said, so far, this is the only photo that has given me a powerful message!!  Wonderful creativity!!!   9', '2003-11-22 10:44:14.000000', NULL, 1),
(492283, 47535, 2223, '<td valign="top">This could be a picture of a poster i have seen. If it isn''t then how did you get the text?</td>', 'This could be a picture of a poster i have seen. If it isn''t then how did you get the text?', '2003-11-22 11:04:58.000000', NULL, 1),
(492289, 46722, 6477, '<td valign="top">funny and lovely "big ears" model:)</td>', 'funny and lovely "big ears" model:)', '2003-11-22 11:25:11.000000', NULL, 1),
(492349, 47541, 9411, '<td valign="top">Good reconstruction of a classic. Would have like the hand a bit sharper. 7</td>', 'Good reconstruction of a classic. Would have like the hand a bit sharper. 7', '2003-11-22 14:24:34.000000', NULL, 1),
(492351, 47708, 9411, '<td valign="top">Yes.  I hope you had some vaseline under that duct tape.  I like your use of an angled crop to give this more interest. 7</td>', 'Yes.  I hope you had some vaseline under that duct tape.  I like your use of an angled crop to give this more interest. 7', '2003-11-22 14:25:35.000000', NULL, 1),
(492352, 47503, 9411, '<td valign="top">Good urban capture. I  like the limited colours. 8</td>', 'Good urban capture. I  like the limited colours. 8', '2003-11-22 14:26:14.000000', NULL, 1),
(492354, 46722, 9411, '<td valign="top">Good idea, cute critter. Personally I don''t like screen shot inclusions. Most are too soft on focus.  Possibly printing the advert and creating a curved background to wrap around the chinchilla could have elevated this shot.  I do like it being black and white.  6</td>', 'Good idea, cute critter. Personally I don''t like screen shot inclusions. Most are too soft on focus.  Possibly printing the advert and creating a curved background to wrap around the chinchilla could have elevated this shot.  I do like it being black and white.  6', '2003-11-22 14:28:29.000000', NULL, 1),
(492382, 47616, 4090, '<td valign="top">great "shot" but lacks the focus on the needle 9/10</td>', 'great "shot" but lacks the focus on the needle 9/10', '2003-11-22 17:19:23.000000', NULL, 1),
(492385, 47478, 3697, '<td valign="top">what a unique take on this week''s assignment. Very good focus and lighting... overall a very effective bit of "propaganda".</td>', 'what a unique take on this week''s assignment. Very good focus and lighting... overall a very effective bit of "propaganda".', '2003-11-22 17:31:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(492388, 47540, 13789, '<td valign="top">You ever think all these crowds are all photographers and videographers?</td>', 'You ever think all these crowds are all photographers and videographers?', '2003-11-22 17:48:46.000000', NULL, 1),
(492391, 47408, 13789, '<td valign="top">very funny.</td>', 'very funny.', '2003-11-22 17:56:39.000000', NULL, 1),
(492467, 47607, 13728, '<td valign="top">I understand better now, thanks for your reply to my comments.  although I was certainly around then, I just didn''t remember the song and didn''t relate the title.  Thanks for the explanation.  It is still a real nice shot, even better when I understand!</td>', 'I understand better now, thanks for your reply to my comments.  although I was certainly around then, I just didn''t remember the song and didn''t relate the title.  Thanks for the explanation.  It is still a real nice shot, even better when I understand!', '2003-11-22 23:06:06.000000', NULL, 1),
(492469, 47718, 12661, '<td valign="top">Hmmm. I''m not sure why, but I think this photo could use a bit of spot editing. ;)</td>', 'Hmmm. I''m not sure why, but I think this photo could use a bit of spot editing. ;)', '2003-11-22 23:11:38.000000', NULL, 1),
(492470, 47723, 10402, '<td valign="top">Wonderful execution of a great idea! The lighting is perfect. Good composition and nice soft focus.<br/> <br/>(And I actually recognize Lauren in this one!)</td>', 'Wonderful execution of a great idea! The lighting is perfect. Good composition and nice soft focus. (And I actually recognize Lauren in this one!)', '2003-11-22 23:12:41.000000', NULL, 1),
(492472, 47705, 12661, '<td valign="top">I''m interpreting this as the speaker of the truth doesn''t have access to the microphone (it''s too far away). If that''s the case, then WOW. Strong message. Using DOF really helps bring out the meaning. Very well done.</td>', 'I''m interpreting this as the speaker of the truth doesn''t have access to the microphone (it''s too far away). If that''s the case, then WOW. Strong message. Using DOF really helps bring out the meaning. Very well done.', '2003-11-22 23:19:55.000000', NULL, 1),
(492473, 47687, 10402, '<td valign="top">A nice assortment of knives, artfully arranged. The gradient background is nice. The focus is too soft for the subject; it needs some sharpening. But your interpretation of the beauty and variety of knives is too neutral to be propaganda.</td>', 'A nice assortment of knives, artfully arranged. The gradient background is nice. The focus is too soft for the subject; it needs some sharpening. But your interpretation of the beauty and variety of knives is too neutral to be propaganda.', '2003-11-22 23:21:01.000000', NULL, 1),
(492474, 47415, 12661, '<td valign="top">I like the concept, but I think the keys are too hidden. Showing the entire key would have had a bigger impact.</td>', 'I like the concept, but I think the keys are too hidden. Showing the entire key would have had a bigger impact.', '2003-11-22 23:22:34.000000', NULL, 1),
(492475, 47462, 10402, '<td valign="top">The ghosted artist is very subtle; I didn''t notice him at first. It adds a nice touch to the image; I like it.</td>', 'The ghosted artist is very subtle; I didn''t notice him at first. It adds a nice touch to the image; I like it.', '2003-11-22 23:24:14.000000', NULL, 1),
(492476, 47408, 12661, '<td valign="top">If you had managed to put a bow tie on the bird, I''d have given you a 10!!! Thanks for the laugh.</td>', 'If you had managed to put a bow tie on the bird, I''d have given you a 10!!! Thanks for the laugh.', '2003-11-22 23:25:03.000000', NULL, 1),
(492477, 47545, 10402, '<td valign="top">I''m not sure what cause the image is trying to promote, but it is a great photo of this statue. The viewpoint emphasizes the player''s height. The trees and sky make a nice background.</td>', 'I''m not sure what cause the image is trying to promote, but it is a great photo of this statue. The viewpoint emphasizes the player''s height. The trees and sky make a nice background.', '2003-11-22 23:27:35.000000', NULL, 1),
